<script setup lang="ts">
import { ref,computed,onMounted,onBeforeUnmount,watch } from 'vue';
import {api} from '../api';import DataPanel from './DataPanel.vue';import DocumentViewer from './DocumentViewer.vue';import StatusBadge from './StatusBadge.vue';import HelpNote from './HelpNote.vue';import NextStep from './NextStep.vue';import IssueReview from './IssueReview.vue';import {bankTabLabel,explainStatus,guideFor,helpText,plainFailure,reviewIssues,smoothScroll} from '../customerLanguage';
const props=defineProps<{file:any}>();const emit=defineEmits(['refresh','guide']);
const state=ref<any>({}),error=ref(''),notice=ref(''),busy=ref(false),tab=ref('progress'),runId=ref(''),source=ref<any>(),upload=ref<File>(),fictional=ref(false),selectedVersions=ref<number[]>([]),selectedAccounts=ref<string[]>([]),selectedTx=ref<number[]>([]),query=ref(''),filter=ref(''),category=ref('unresolved'),include=ref('policy'),reason=ref('source_verified'),notes=ref(''),ruleId=ref(''),workflow=ref('business'),months=ref(12),endMonth=ref(new Date().toISOString().slice(0,7)),ownership=ref(''),remaining=ref(''),accountA=ref(''),accountB=ref(''),condition=ref(''),explanation=ref(''),publicExplanation=ref(''),messageKind=ref('explanation'),preview=ref<any>(),ruleName=ref(''),ruleStatus=ref('draft'),ruleJson=ref('');
const internal=computed(()=>props.file.permissions.review),root=computed(()=>'/api/files/'+props.file.id+'/bank'),runRoot=computed(()=>root.value+'/runs/'+state.value.run?.id),versions=computed(()=>props.file.documents.filter((d:any)=>d.category!=='fixture').flatMap((d:any)=>d.versions)),tx=computed(()=>state.value.transactions?.filter((t:any)=>(!filter.value||t.current_category===filter.value)&&(!query.value||(t.data.description+' '+t.posting_date+' '+t.id).toLowerCase().includes(query.value.toLowerCase())))||[]),latest=computed(()=>state.value.calculations?.at(-1)),sourceVersion=computed(()=>versions.value.find((v:any)=>v.id===source.value?.document_version_id)),tabs=computed(()=>internal.value?['progress','documents','coverage','transactions','transfers','income','nsf','sustainability','integrity','conditions','history','reports']:['income','documents','conditions','reports']);
const guide=computed(()=>guideFor({documents:versions.value.length,runStatus:state.value.run?.status||null,hasReport:!!state.value.reports?.length,canReview:internal.value,subject:'bank statements',failure:state.value.run?.error_code}));
watch(guide,(g)=>emit('guide',g),{immediate:true});
const issues=computed(()=>internal.value?reviewIssues(state.value.findings||[]):[]);
const detailsOpen=ref(false);
function reveal(next:string){tab.value=next;detailsOpen.value=true}
function onGuideAction(){const cta=guide.value.cta;if(cta==='upload')reveal('documents');else if(cta==='start'||cta==='retry')reveal('progress');else if(cta==='export')reveal('reports');else if(cta==='review'){if(issues.value.length)document.getElementById('issue-review')?.scrollIntoView({behavior:smoothScroll(),block:'start'});else reveal(internal.value?'integrity':'conditions')}}
let poll:ReturnType<typeof setInterval>;
async function load(){try{const prior=state.value.run?.status;state.value=await api(root.value+(runId.value?'?run_id='+encodeURIComponent(runId.value):''));if(state.value.run)runId.value=state.value.run.id;if(['Queued','Validating','Extracting','Reconciling','Analyzing'].includes(prior)&&['Completed','PartiallyCompleted','NeedsReview','Failed'].includes(state.value.run?.status))emit('refresh');for(const statement of state.value.statements||[])statement.edit={};if(!selectedVersions.value.length)selectedVersions.value=props.file.documents.filter((d:any)=>d.category!=='fixture').map((d:any)=>d.versions.at(-1)?.id).filter(Boolean);}catch(e:any){error.value=e.message;if([403,404].includes(e.status)){state.value={};source.value=null;emit('refresh')}}}
async function act(fn:()=>Promise<any>,text:string){error.value='';busy.value=true;try{const r=await fn();notice.value=text;await load();return r}catch(e:any){error.value=e.message}finally{busy.value=false}}
onMounted(async()=>{if(!internal.value)tab.value='income';else if(!versions.value.length)tab.value='documents';await load();poll=setInterval(()=>{if(['Queued','Validating','Extracting','Reconciling','Analyzing'].includes(state.value.run?.status))load()},3000)});onBeforeUnmount(()=>clearInterval(poll));
async function addDocument(){if(!upload.value)return;const fd=new FormData;fd.append('file',upload.value);fd.append('fictional_sample',fictional.value?'1':'0');await act(()=>api('/api/files/'+props.file.id+'/documents','POST',fd),'Original preserved in quarantine. New inputs never rewrite old reports.');emit('refresh')}
async function start(){const r=await act(()=>api(root.value+'/runs','POST',{idempotency_key:crypto.randomUUID(),document_version_ids:selectedVersions.value,rule_id:ruleId.value?Number(ruleId.value):null,workflow:workflow.value,months:months.value,end_month:endMonth.value,...(ownership.value?{ownership_percent:ownership.value}:{}),...(remaining.value?{remaining_percent:remaining.value}:{})}),'Pinned analysis queued. Provider/scanner failures will be explicit.');if(r){runId.value=r.run_id;await load()}}
function calcChoices(){return {account_keys:selectedAccounts.value,...(ownership.value?{ownership_percent:ownership.value}:{}),...(remaining.value?{remaining_percent:remaining.value}:{})}}
async function calculate(isPreview=false,pending=false){const r=await act(()=>api(runRoot.value+'/calculate','POST',{...calcChoices(),reason_code:reason.value,notes:notes.value,preview:isPreview,...(pending?{preview_transactions:selectedTx.value.map(id=>({id,category:category.value,include:include.value==='policy'?null:include.value==='yes'}))}:{})}),isPreview?'Impact preview only; no snapshot or decision saved.':'New immutable calculation snapshot saved.');if(isPreview&&r)preview.value=r}
async function reviewTx(){await act(()=>api(runRoot.value+'/reviews','POST',{kind:'transaction',transaction_ids:selectedTx.value,category:category.value,include:include.value==='policy'?null:include.value==='yes',reason_code:reason.value,notes:notes.value}),'Review recorded; original extraction/suggestions retained. Recalculate income.');selectedTx.value=[]}
async function correctTx(t:any){const correction:any={};for(const [local,field] of [['correctDate','posting_date'],['correctCredit','credit'],['correctDebit','debit'],['correctBalance','running_balance']])if(t[local]!==undefined)correction[field]=t[local]===''?null:t[local];if(!Object.keys(correction).length){error.value='Enter at least one source correction.';return}await act(()=>api(runRoot.value+'/reviews','POST',{kind:'transaction',transaction_ids:[t.id],category:t.current_category,include:t.include,correction,reason_code:'extraction_correction',notes:notes.value}),'Correction saved separately from immutable extraction; reconcile and recalculate.')}
const statementFields=['institution','holder','masked_account','currency','period_start','period_end','opening_balance','closing_balance','reported_credits','reported_debits','reported_fees'];
async function correctStatement(s:any){const correction:any={};for(const key of statementFields)if(s.edit[key]!==undefined)correction[key]=s.edit[key]===''?null:s.edit[key];if(s.edit.fees_separate_from_debits!==undefined)correction.fees_separate_from_debits=s.edit.fees_separate_from_debits==='true';if(s.edit.complete!==undefined)correction.complete=s.edit.complete==='true';await act(()=>api(runRoot.value+'/reviews','POST',{kind:'statement',statement_id:s.id,statement_correction:correction,...(s.canonical?{canonical_account_key:s.canonical}:{}),reason_code:'extraction_correction',notes:notes.value}),'Statement correction appended. Identity corrections require fresh account confirmation; recalculate.')}
function minorText(n:number|null){return n===null?'unreadable':(n/100).toFixed(2)}
async function verifyDaily(s:any){await act(()=>api(runRoot.value+'/reviews','POST',{kind:'statement',statement_id:s.id,daily_reconstruction_verified:true,reason_code:'source_verified',notes:notes.value}),'Daily reconstruction source review recorded. It is used only if all ledger arithmetic and dates reconcile.')}
async function verify(a:any){await act(()=>api(runRoot.value+'/reviews','POST',{kind:'account',account_key:a.account_key,designation:a.designation,verified:!a.verified,reason_code:reason.value,notes:notes.value}),'Account identity/designation verification recorded.')}
async function relationship(){await act(()=>api(runRoot.value+'/relationships','POST',{account_a:accountA.value,account_b:accountB.value,verified:true,reason_code:reason.value,notes:notes.value}),'Relationship verified; same-file matching recomputed.')}
async function transfer(m:any,status:string){const amount=m.allocationInput||String(m.data.amount_minor);await act(()=>api(runRoot.value+'/transfers/'+m.id,'POST',{status,...(status==='confirmed'?{amount_minor:Number(amount)}:{}),reason_code:reason.value,notes:notes.value}),'Transfer review saved. Allocations cannot exceed either transaction.')}
async function finding(f:any){await act(()=>api(runRoot.value+'/findings/'+f.id,'POST',{status:f.nextStatus||'reviewed',reason_code:reason.value,notes:notes.value,...(f.assigneeInput?{assignee:Number(f.assigneeInput)}:{})}),'Finding history appended; no automatic mortgage decision.')}
function showSource(t:any){source.value={document_version_id:t.document_version_id,page:t.data.page,excerpt:t.data.excerpt,...(t.data.region_verified&&t.data.region?{region:{x:t.data.region[0],y:t.data.region[1],width:t.data.region[2],height:t.data.region[3],normalized:true}}:{})}}
async function issue(final:boolean){if(!latest.value)return;await act(()=>api(runRoot.value+'/reports','POST',{calculation_id:latest.value.id,final,public_explanation:publicExplanation.value}),final?'Income report finalized (not mortgage approval). Separate broker-safe report issued.':'Preliminary internal report issued with open conditions/completeness recorded.')}
function samplePolicy(){return {workflow:workflow.value,eligible_categories:workflow.value==='business'?['business_revenue']:['payroll_income','owner_distribution'],expense_treatment:workflow.value==='business'?'remaining_percent':'none',remaining_percent:workflow.value==='business'?'50.00':null,ownership_required:workflow.value==='business',fixed_ownership_percent:null,rounding:'HALF_UP',required_evidence:['full_selected_months','verified_accounts','reviewed_transactions'],allow_provisional:true,approval_reference:null,require_external_integrity:true,require_no_open_findings:true,approved_thresholds:false,nsf_convention:'Explicit non-fee events; fees do not create a second event',nsf_review_event_threshold:1,liquidity_threshold_minor:100000}}
async function saveRule(){await act(()=>api(root.value+'/rules','POST',{name:ruleName.value,status:ruleStatus.value,policy:JSON.parse(ruleJson.value)}),'New immutable policy version saved. Existing runs remain pinned to their original policy.')}
</script>
<template><section class="bank-workspace"><p class="alert" v-if="error" role="alert">{{error}}</p><p class="alert success" v-if="notice" role="status">{{notice}}</p><NextStep :guide="guide" @act="onGuideAction"/><p class="micro">The tool only flags potential issues. It does not approve or decline a loan.</p><IssueReview v-if="issues.length" :issues="issues" :versions="versions"/><details class="more-details" :open="detailsOpen" @toggle="detailsOpen=($event.target as HTMLDetailsElement).open"><summary>{{internal?'Statement details':'More about this file'}}</summary><p class="micro">No simulated analysis in this workspace. These details stay here so the next step above stays easy to see.</p><div class="actions"><label v-if="internal">Run history<select v-model="runId" @change="load"><option value="">Latest run</option><option v-for="r in state.runs" :key="r.id" :value="r.id">{{explainStatus(r.status).label}}</option></select></label><button :disabled="busy" @click="load">Refresh</button></div><div class="tabs" role="tablist"><button v-for="t in tabs" :key="t" role="tab" :id="'bank-tab-'+t" :aria-controls="'bank-panel-'+t" :aria-selected="tab===t" :class="{active:tab===t}" @click="tab=t">{{bankTabLabel[t]||t}}</button></div>
<div :class="['review-layout',{'with-source':source}]"><section class="content-card" role="tabpanel" :id="'bank-panel-'+tab" :aria-labelledby="'bank-tab-'+tab">
<template v-if="tab==='progress'&&internal"><h2>Run and exact input versions</h2><p v-if="state.run" role="status"><StatusBadge :code="state.run.status"/> <span v-if="state.run.error_code" class="status-help">{{plainFailure(state.run.error_code)}}</span></p><p v-if="state.run&&!state.inputs_fresh" class="alert warning">Newer documents were uploaded after this run. Start a new review for them. Old issued reports are unchanged.</p><div v-if="state.run" class="actions"><button :disabled="busy||!['Failed','PartiallyCompleted'].includes(state.run.status)" @click="act(()=>api(runRoot+'/control/retry','POST'), 'Pinned run retry requested.')">Retry pinned run</button><button :disabled="busy||!['Queued','Validating','Extracting','Reconciling','Analyzing'].includes(state.run.status)" @click="act(()=>api(runRoot+'/control/cancel','POST'),'Cancellation requested; active provider request may finish without another submission.')">Cancel</button></div><DataPanel :data="state.scans||[]"/><DataPanel :data="state.provider_usage||[]"/><form class="form-stack" @submit.prevent="start"><h3>Start real analysis</h3><label>Workflow<select v-model="workflow"><option>business</option><option>personal</option></select></label><label>Selected period<select v-model.number="months"><option :value="12">12 months</option><option :value="24">24 months</option></select></label><label>Last selected month<input type="month" v-model="endMonth" required/></label><label>Versioned rule<select v-model="ruleId"><option value="">No approved profile — calculation withheld</option><option v-for="r in state.rules" :value="r.id">{{r.name}} v{{r.version}} · {{r.status}}</option></select></label><fieldset><legend>Pin original document versions (include supporting business statements)</legend><label v-for="v in versions" :key="v.id" class="check"><input type="checkbox" :value="v.id" v-model="selectedVersions"/>{{v.original_name}} v{{v.version}} · SHA {{v.sha256.slice(0,12)}}</label></fieldset><button class="primary" :disabled="busy||!selectedVersions.length">Start processing</button></form><details><summary>Create a versioned policy (not an invented lender policy)</summary><p>Draft/example rules cannot finalize income. An approved policy requires actual approval reference and configured completeness gates.</p><form class="form-stack" @submit.prevent="saveRule"><label>Profile name<input v-model="ruleName" required/></label><label>Status<select v-model="ruleStatus"><option>draft</option><option>approved</option><option v-if="file.is_demo">example</option></select></label><button type="button" @click="ruleJson=JSON.stringify(samplePolicy(),null,2);ruleStatus='draft'">Fill clearly unconfirmed draft structure</button><label>Explicit policy JSON<textarea rows="18" v-model="ruleJson" required/></label><button :disabled="busy">Save new version</button></form></details></template>
<template v-else-if="tab==='documents'"><h2>Private immutable originals</h2><form v-if="file.permissions.upload" class="form-stack" @submit.prevent="addDocument"><label>PDF / JPEG / PNG · max 20 MiB<input type="file" accept=".pdf,.png,.jpg,.jpeg" @change="upload=($event.target as HTMLInputElement).files?.[0]" required/></label><label class="check"><input type="checkbox" v-model="fictional"/>This is a fictional fixture (only explicit local/test scanner bypass can apply).</label><button class="primary" :disabled="busy">Upload bank statements</button><small>If the status says not virus-scanned, no malware check ran. The file is stored, and it is not certified clean. A password-protected PDF needs an unlocked copy.</small></form><article v-for="v in versions" :key="v.id" class="document-card"><h3>{{v.original_name}} v{{v.version}}</h3><StatusBadge v-if="v.scan_status" :code="v.scan_status"/><small>{{v.bytes}} bytes · immutable SHA-256 {{v.sha256}}</small><button @click="source={document_version_id:v.id,page:1}">View authorized original</button></article></template>
<template v-else-if="tab==='coverage'&&internal"><h2>Statement/account coverage</h2><p>Matching masked IDs is only an unverified account candidate. Verify the actual identity and designation before relationship matching/final income.</p><article class="card" v-for="a in state.accounts" :key="a.account_key"><h3>{{a.institution}} · {{a.masked_account}} · {{a.holder}}</h3><label>Designation<select v-model="a.designation"><option>business</option><option>personal</option></select></label><button :disabled="busy" @click="verify(a)">{{a.verified?'Revoke identity verification':'Confirm account identity/designation'}}</button></article><article v-for="s in state.statements" class="card"><h3>Statement {{s.id}} · {{s.data.period_start}} to {{s.data.period_end}}</h3><details><summary>Correct statement metadata / reconcile source totals</summary><form class="form-grid" @submit.prevent="correctStatement(s)"><label v-for="field in statementFields">{{field}}<input v-model="s.edit[field]" :placeholder="String(s.data[field]??'unresolved')"/></label><label>Fees excluded from reported debits<select v-model="s.edit.fees_separate_from_debits"><option :value="undefined">Unchanged</option><option value="true">Yes — extracted debits must still include fee transactions</option><option value="false">No — do not subtract fees twice</option></select></label><label>Source extraction completeness<select v-model="s.edit.complete"><option :value="undefined">Unchanged</option><option value="true">All source pages/ledger entries verified</option><option value="false">Incomplete</option></select></label><label>Same verified account identity (explicit source notes required)<select v-model="s.canonical"><option value="">Keep current candidate</option><option v-for="a in state.accounts?.filter((a:any)=>a.verified)" :value="a.account_key">{{a.institution}} · {{a.masked_account}} · {{a.holder}}</option></select></label><button :disabled="busy">Append statement correction</button></form></details><p>Daily reconstruction is only valid after verifying complete source coverage, every posting and opening/closing balance.</p><button :disabled="busy" @click="verifyDaily(s)">Confirm complete ledger for daily reconstruction (notes required)</button></article><DataPanel :data="state.statements||[]"/></template>
<template v-else-if="tab==='transactions'&&internal"><h2>Transaction classification ≠ eligibility</h2><div class="form-grid"><label>Search<input v-model="query" placeholder="Description, date, ID"/></label><label>Category filter<select v-model="filter"><option value="">All</option><option v-for="c in state.categories">{{c}}</option></select></label><label>New category<select v-model="category"><option v-for="c in state.categories">{{c}}</option></select></label><label>Eligibility decision<select v-model="include"><option value="policy">Use selected deterministic policy</option><option value="yes">Reviewer explicitly includes</option><option value="no">Reviewer explicitly excludes</option></select></label></div><div class="actions"><button :disabled="busy||!selectedTx.length" @click="reviewTx">Save bulk review</button><button :disabled="busy||!selectedTx.length||!selectedAccounts.length" @click="calculate(true,true)">Preview pending decision impact</button></div><div class="table-wrap"><table><thead><tr><th>Select</th><th>Date / original description</th><th>Credit / debit (minor USD)</th><th>Suggestion / current / eligibility</th><th>Source</th></tr></thead><tbody><tr v-for="t in tx" :key="t.id"><td><input type="checkbox" :aria-label="'Select transaction '+t.id" v-model="selectedTx" :value="t.id"/></td><td>{{t.posting_date||'Unresolved date'}}<small>{{t.data.description}}</small></td><td>{{t.credit_minor??'—'}} / {{t.debit_minor??'—'}}</td><td>Original: {{t.data.category_suggestion}}<small>Initial: {{t.data.initial_category}} · current: {{t.current_category}} · {{t.include===null?'policy':(t.include?'included':'excluded')}}</small></td><td><details><summary>Correct extracted values (reason notes required)</summary><label>Posting date<input type="date" v-model="t.correctDate" :placeholder="t.posting_date"/></label><label>Credit USD<input v-model="t.correctCredit" :placeholder="minorText(t.credit_minor)"/></label><label>Debit USD<input v-model="t.correctDebit" :placeholder="minorText(t.debit_minor)"/></label><label>Running balance USD<input v-model="t.correctBalance" :placeholder="minorText(t.balance_minor)"/></label><button :disabled="busy" @click="correctTx(t)">Append source correction</button></details><button @click="showSource(t)">View page {{t.data.page}}{{t.data.region_verified?' · verified location':''}}</button></td></tr></tbody></table></div><DataPanel v-if="preview" :data="preview"/></template>
<template v-else-if="tab==='transfers'&&internal"><h2>Verified relationships and explicit allocations</h2><p>Equal amounts alone never prove a transfer. Split/combined and ambiguous candidates remain reviewable. Partial allocations cannot exceed either side.</p><form class="form-grid" @submit.prevent="relationship"><label>Verified account A<select v-model="accountA" required><option value="">Select</option><option v-for="a in state.accounts?.filter((x:any)=>x.verified)" :value="a.account_key">{{a.masked_account}} · {{a.designation}}</option></select></label><label>Verified related account B<select v-model="accountB" required><option value="">Select</option><option v-for="a in state.accounts?.filter((x:any)=>x.verified)" :value="a.account_key">{{a.masked_account}} · {{a.designation}}</option></select></label><button :disabled="busy">Verify relationship and match</button></form><article v-for="m in state.transfers" class="finding-card"><h3>Debit {{m.data.source_id}} → credit {{m.data.destination_id}} · {{m.status}}</h3><DataPanel :data="m.data.evidence"/><label>Explicit allocated amount (minor USD)<input v-model="m.allocationInput" type="number" min="1" :placeholder="String(m.data.amount_minor)"/></label><div class="actions"><button :disabled="busy" @click="transfer(m,'confirmed')">Confirm allocation</button><button :disabled="busy" @click="transfer(m,'rejected')">Reject candidate</button></div></article></template>
<template v-else-if="tab==='income'"><h2>Qualifying income</h2><HelpNote :text="helpText.income"/><template v-if="internal"><fieldset><legend>Explicitly included income accounts (supporting business accounts are not personal income)</legend><label v-for="a in state.accounts" class="check"><input type="checkbox" v-model="selectedAccounts" :value="a.account_key"/>{{a.masked_account}} · {{a.designation}} · {{a.verified?'verified':'unverified'}}</label></fieldset><div class="form-grid"><label>Confirmed ownership %<input v-model="ownership" type="number" min="0" max="100" step="0.0001"/></label><label>Share of income left after expenses (%)<input v-model="remaining" type="number" min="0" max="100" step="0.0001"/></label></div><div class="actions"><button :disabled="busy||!state.run||!selectedAccounts.length" @click="calculate(true)">Preview this change</button><button class="primary" :disabled="busy||!state.run||!selectedAccounts.length" @click="calculate()">Save this income figure</button></div><DataPanel v-if="preview" :data="preview"/><DataPanel :data="latest?.data||{notice:'Select inputs and complete extraction/review. No income inferred.'}"/></template><DataPanel v-else :data="state.final_income||{notice:'No final income report issued.'}"/></template>
<template v-else-if="tab==='nsf'&&internal"><h2>NSF and overdrafts</h2><HelpNote :text="helpText.nsf"/><DataPanel :data="latest?.data.nsf||{notice:'No calculation snapshot'}"/><h3>Supporting accounts — separate actual coverage, not the income lookback numerator</h3><DataPanel :data="latest?.data.supporting_account_nsf||{}"/><DataPanel :data="state.findings?.filter((f:any)=>f.data.category==='nsf_review')||[]"/><button @click="tab='integrity'">Record current reviewer disposition</button></template><template v-else-if="tab==='sustainability'&&internal"><h2>Restricted business sustainability</h2><DataPanel :data="latest?.data.sustainability||{notice:'No calculation snapshot'}"/><DataPanel :data="state.findings?.filter((f:any)=>f.data.category==='sustainability_review')||[]"/><button @click="tab='integrity'">Record current reviewer disposition</button></template>
<template v-else-if="tab==='integrity'&&internal"><h2>Internal integrity and independent specialist completeness</h2><DataPanel :data="state.integrity||{}"/><article v-for="f in state.findings" :key="f.id" class="finding-card"><span class="badge">{{f.data.category}} · {{f.data.severity}} · {{f.status}}</span><h3>{{f.data.code}}</h3><p>{{f.data.observation}}</p><p>{{f.data.explanation}}</p><button v-if="f.data.document_version_id" @click="source={document_version_id:f.data.document_version_id,page:f.data.page||1}">Source evidence</button><label>Reviewer action<select v-model="f.nextStatus"><option>reviewed</option><option>explanation_requested</option><option>resolved</option><option>rejected</option><option>escalated</option><option>reopened</option></select></label><label>Assign authorized reviewer user ID<input type="number" min="1" v-model="f.assigneeInput"/></label><button :disabled="busy" @click="finding(f)">Record disposition with reason</button></article></template>
<template v-else-if="tab==='conditions'"><h2>Deliberately public conditions / explanations</h2><DataPanel :data="state.conditions||[]"/><div v-if="internal" class="actions"><button v-for="c in state.conditions" :disabled="busy" @click="act(()=>api(runRoot+'/conditions','POST',{condition_id:c.id,text:c.text,status:c.status==='satisfied'?'open':'satisfied',public_acknowledgement:true}),'Public condition status appended; original retained.')">{{c.status==='satisfied'?'Reopen':'Satisfy'}} condition {{c.id}}</button></div><DataPanel :data="state.messages||[]"/><form v-if="internal&&state.run" class="form-stack" @submit.prevent="act(()=>api(runRoot+'/conditions','POST',{text:condition,status:'open',public_acknowledgement:true}),'Deliberately public condition saved.')"><label>Broker-visible wording — never copy restricted findings automatically<textarea v-model="condition" required/></label><button :disabled="busy">Publish this condition to authorized file users</button></form><form class="form-stack" @submit.prevent="act(()=>api(root+'/messages','POST',{text:explanation,kind:messageKind}),'Explanation / review request submitted.')"><label>Purpose<select v-model="messageKind"><option>explanation</option><option>review_request</option></select></label><label>Public explanation / request<textarea v-model="explanation" required/></label><button :disabled="busy">Submit to file reviewers</button></form></template>
<template v-else-if="tab==='history'&&internal"><h2>Append-only decisions and snapshots</h2><DataPanel :data="state.review_history||[]"/><DataPanel :data="state.condition_history||[]"/><DataPanel :data="state.calculations?.map((c:any)=>({id:c.id,hash:c.data.snapshot_hash,status:c.data.status,created_at:c.created_at}))||[]"/></template>
<template v-else-if="tab==='reports'"><h2>Versioned real exports</h2><template v-if="internal"><p>Preliminary reports may contain findings. Final income requires configured, approved completeness gates; it is not mortgage approval.</p><label>Deliberately broker-safe final explanation<textarea v-model="publicExplanation"/></label><div class="actions"><button :disabled="busy||!latest" @click="issue(false)">Issue preliminary internal report</button><button :disabled="busy||!latest" @click="issue(true)">Finalize income + separate broker report</button></div></template><article v-for="r in state.reports" class="document-card"><strong>Report {{r.data?.report_version||r.version}} · {{r.data?.audience||'broker'}} · {{r.data?.status||'final'}}</strong><div class="actions"><a v-for="format in ['xlsx','csv','pdf']" class="button" :href="root+'/runs/'+r.run_id+'/reports/'+r.id+'/'+format">Download {{format.toUpperCase()}}</a></div></article></template>
<fieldset v-if="internal" class="form-stack"><legend>Reviewer governance (applies to transaction/account/relationship/transfer/finding actions)</legend><label>Standard reason code<select v-model="reason"><option v-for="c in state.reason_codes">{{c}}</option></select></label><label>Review notes (required for financial input confirmation, source corrections, Other, resolution or rejection)<textarea v-model="notes" maxlength="4000"/></label></fieldset>
</section><aside v-if="source" class="source-pane"><div class="section-heading"><h3>Preserved original source</h3><button @click="source=null">Close</button></div><p>{{source.excerpt}}</p><p>Page-only reference unless the native location is verified.</p><DocumentViewer v-if="sourceVersion" :version="sourceVersion" :page="source.page" :region="source.region"/><p v-else>Source version is not available to your role.</p></aside></div></details></section></template>
